        { t: "ثلاث فئات للأعضاء", d: "الموظفون القنصليون، والمستخدمون القنصليون، وأعضاء طاقم الخدمة (المادة 1/1(ز)).", pg: "396–397" },
        { t: "العامل والفخري", d: "العامل موظف متفرغ بمرتب منتظم، والفخري مقيم بلا مرتب منتظم يزاول نشاطًا مربحًا.", pg: "396–397" }
