  night: [
    { x: "الأداة اللامركزية لإدارة العلاقات الدولية: البعثات الدبلوماسية والقنصلية؛ والمركزية: رئيس الدولة، ورئيس الحكومة، ووزير الخارجية، والقائد العام للقوات المسلحة في الحروب أو المنازعات المسلحة.", pg: "381–382" },
    { x: "بدأت العلاقات الدبلوماسية بالبعثات المؤقتة، ثم نشأ التمثيل الدائم لعدم كفايتها؛ ويراه بعض الفقه بين معاهدة وستفاليا 1648 ومؤتمر فيينا 1815.", pg: "383" },
    { x: "تكاد التعريفات تُجمع على أن الدبلوماسية علم وفن تمثيل أشخاص القانون الدولي في علاقاتهم المتبادلة؛ ومصادر القانون الدبلوماسي أربعة، وأولها في المعاهدات اتفاقية فيينا لعام 1961 (53 مادة، نافذة في 24 أبريل 1964، و190 طرفًا).", pg: "383–385" },
    { x: "حجم البعثة بالاتفاق (وعند غيابه المادة 1/11)؛ ورؤساء البعثات ثلاث مراتب (المادة 1/14): السفراء ومن في درجتهم، ثم المبعوثون والوزراء المفوضون، ثم القائمون بالأعمال لدى وزراء الخارجية؛ والأعضاء أربع فئات.", pg: "385–386" },
    { x: "أساس الحصانات ثلاث نظريات: الامتداد الإقليمي (فكرة خيالية، وأول من نادى بها جروسيوس)، والصفة التمثيلية (مونتسكيو في «روح القوانين»، وأيدها فاتيل وفوشي)، ومقتضيات الوظيفة (أساس واقعي)؛ ومزجت اتفاقية فيينا 1961 بين الأخيرتين في الفقرة قبل الأخيرة من ديباجتها.", pg: "388–389" },
    { x: "وظائف البعثة سبع (المادتان 3 و45، على سبيل المثال)، وواجباتها خمسة (المادتان 41 و42)؛ وحصانات المقر أربع، والحصانات الشخصية ست، وأعلاها للأعضاء الدبلوماسيين وأسرهم.", pg: "387، 390" },
    { x: "الحصانة القضائية للمبعوث: إعفاء كامل من القضاء الجنائي أيًّا كانت جسامة الجريمة، ونسبي من المدني والإداري بأربعة استثناءات على سبيل الحصر، وإعفاء من الشهادة؛ ويُحاكم أمام قضاء دولته (المادة 4/31).", pg: "391" },
    { x: "للدولة الموفد إليها أن تعلن في أي وقت ودون إبداء أسباب أن المبعوث شخص غير مرغوب فيه (المادتان 9 و43(ب))، فيغادر خلال مدة معقولة، وإلا جاز رفض الاعتراف به فيُجرَّد من حصاناته.", pg: "392" },
    { x: "ترتيب الظهور: البعثات الدبلوماسية الخاصة المؤقتة، ثم القنصلية (جذورها قبل ميلاد المسيح عليه السلام)، ثم الدبلوماسية الدائمة؛ والقانون القنصلي نشأ عبر الاتفاقيات الثنائية لا عرفيًا كالدبلوماسي، ودُوّن في اتفاقية فيينا لعام 1963.", pg: "393" },
    { x: "اتفاقية فيينا للعلاقات القنصلية 1963: (79) مادة، نافذة في 19 مارس 1967 بعد (22) دولة (المادة 1/77)، و(179) طرفًا؛ انضمت مصر في 21 يونيو 1965، والسعودية في 29 يونيو 1988.", pg: "394" },
    { x: "بعثة دبلوماسية دائمة واحدة، أما المراكز القنصلية فتتعدد بالاتفاق أو التراضي بين الدولتين (المادتان الثالثة والرابعة): القنصلية العامة، فالقنصلية، فالنيابة القنصلية، فالوكالة القنصلية؛ والعمل خارج الدائرة في الظروف الاستثنائية بموافقة الدولة الموفد إليها (المادة 6).", pg: "394–395" },
    { x: "الرؤساء أربع درجات (المادة 1/9)، والأعضاء ثلاث فئات (المادة 1/1(ز))، والموظفون القنصليون نوعان (المادة 2/1): العامل (المبعوث أو المحترف) والفخري (المنتخب أو المختار)؛ ولا تخلط القنصل العامل بالقنصل العام.", pg: "395–396" },
    { x: "وظائف البعثة القنصلية يحددها القانون الداخلي للدولة الموفدة، ويغلب عليها الطابع الإداري والتجاري (المادة الخامسة من اتفاقية فيينا 1963)؛ وللموظف القنصلي الأعمال الدبلوماسية بثلاثة شروط، دون حصانات دبلوماسية (المادة 1/17).", pg: "397–399" },
    { x: "الحصانات القنصلية أضيق بكثير من الدبلوماسية، وأساسها مقتضيات الوظيفة والصفة التمثيلية؛ ولا حصانة من القضاء الجنائي، والحصانة من القضاء المدني والإداري نسبية بأعمال الوظيفة (المادة 1/43) إلا دعويين مدنيتين (المادة 2/43)؛ الأعضاء: المواد 40–57، والفخريون: 58–68.", pg: "399–402" },
    { x: "انتهاء الوظيفة القنصلية: أسبابها أسباب الدبلوماسية كقاعدة عامة، لكن النزاع المسلح وتغيير رئيس أي من الدولتين لا ينهيانها عادةً؛ واتفاقية فيينا 1963 أجملتها في ثلاثة فقط (المادة 25).", pg: "402–403" }
  ],
